    81	/// Serialize f64 -0.0 and -NaN as positive, such that they're considered equal
    82	/// in the key/value store (e.g. for index lookups).
    83	fn serialize_f64<S: Serializer>(value: &f64, serializer: S) -> StdResult<S::Ok, S::Error> {
    84	    let mut value = *value;
    85	    if (value.is_nan() || value == 0.0) && value.is_sign_negative() {
    86	        value = -value;
    87	    }
    88	    serializer.serialize_f64(value)
    89	}
