   109	// Allow hashing Nulls and floats, and hash -0.0 and -NaN as positive.
   110	impl Hash for Value {
   111	    fn hash<H: Hasher>(&self, hasher: &mut H) {
   112	        core::mem::discriminant(self).hash(hasher); // hash the type
   113	        match self {
   114	            Self::Null => {}
   115	            Self::Boolean(v) => v.hash(hasher),
   116	            Self::Integer(v) => v.hash(hasher),
   117	            Self::Float(v) => {
   118	                // Hash -NaN and -0.0 as positive.
   119	                let mut v = *v;
   120	                if (v.is_nan() || v == 0.0) && v.is_sign_negative() {
   121	                    v = -v;
   122	                }
   123	                v.to_bits().hash(hasher)
   124	            }
   125	            Self::String(v) => v.hash(hasher),
   126	        }
   127	    }
   128	}
