   132	// We establish a total order across all types, even though mixed types will
   133	// rarely/never come up: String > Integer/Float > Boolean > Null.
   134	impl Ord for Value {
   135	    fn cmp(&self, other: &Self) -> Ordering {
   136	        match (self, other) {
   137	            (Self::Null, Self::Null) => Ordering::Equal,
   138	            (Self::Boolean(a), Self::Boolean(b)) => a.cmp(b),
   139	            (Self::Integer(a), Self::Integer(b)) => a.cmp(b),
   140	            (Self::Integer(a), Self::Float(b)) => (*a as f64).total_cmp(b),
   141	            (Self::Float(a), Self::Integer(b)) => a.total_cmp(&(*b as f64)),
   142	            (Self::Float(a), Self::Float(b)) => a.total_cmp(b),
   143	            (Self::String(a), Self::String(b)) => a.cmp(b),
   144	
   145	            (Self::Null, _) => Ordering::Less,
   146	            (_, Self::Null) => Ordering::Greater,
   147	            (Self::Boolean(_), _) => Ordering::Less,
   148	            (_, Self::Boolean(_)) => Ordering::Greater,
   149	            (Self::Float(_), _) => Ordering::Less,
   150	            (_, Self::Float(_)) => Ordering::Greater,
   151	            (Self::Integer(_), _) => Ordering::Less,
   152	            (_, Self::Integer(_)) => Ordering::Greater,
   153	            // String is ordered last.
   154	        }
   155	    }
   156	}
